import React, { useState, useEffect } from 'react';
import { getProperty, deleteProperty } from './apiService';
//import { getProperty, updateProperty /* etc */ } from './apiService';


const PropertyDetails = ({ id, onNavigate }) => {
  const [property, setProperty] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const loadProperty = async () => {
      try {
        const data = await getProperty(id);
        setProperty(data);
      } catch (err) {
        setError('Failed to load property details. Please try again later.');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    loadProperty();
  }, [id]);

  const handleDelete = async () => {
    if (window.confirm('Are you sure you want to delete this property?')) {
      try {
        await deleteProperty(id);
        onNavigate('propertyList');
      } catch (err) {
        setError('Failed to delete property. Please try again later.');
        console.error(err);
      }
    }
  };

  if (loading) {
    return <div className="text-center py-10">Loading property details...</div>;
  }

  if (error) {
    return (
      <div className="max-w-2xl mx-auto py-10">
        <div className="bg-red-100 text-red-700 p-4 rounded mb-4">
          {error}
        </div>
        <div className="text-center">
          <button 
            onClick={() => onNavigate('propertyList')}
            className="text-blue-600 hover:underline bg-transparent border-0 cursor-pointer"
          >
            Return to Property List
          </button>
        </div>
      </div>
    );
  }

  if (!property) {
    return (
      <div className="max-w-2xl mx-auto py-10 text-center">
        <h2 className="text-xl font-semibold mb-4">Property Not Found</h2>
        <p className="mb-4">The property you're looking for doesn't exist or has been removed.</p>
        <button 
          onClick={() => onNavigate('propertyList')}
          className="text-blue-600 hover:underline bg-transparent border-0 cursor-pointer"
        >
          Return to Property List
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">{property.property_name}</h1>
        <div className="space-x-2">
          <button
            onClick={() => onNavigate('propertyForm', id, true)}
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 border-0 cursor-pointer"
          >
            Edit
          </button>
          <button
            onClick={handleDelete}
            className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 border-0 cursor-pointer"
          >
            Delete
          </button>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-md overflow-hidden mb-6">
        <div className="p-6">
          <div className="mb-6">
            <h2 className="text-lg font-semibold mb-2">Property Information</h2>
            <p className="text-gray-700 mb-1">
              <span className="font-medium">Address:</span> {property.address}
            </p>
            <p className="text-gray-700 mb-1">
              <span className="font-medium">Price:</span> ${property.price_per_person} per person
            </p>
            <p className="text-gray-700 mb-1">
              <span className="font-medium">Distance to Campus:</span> {property.distance_to_walc} miles
            </p>
            <p className="text-gray-700 mb-1">
              <span className="font-medium">Lease Duration:</span> {property.lease_duration} months
            </p>
            {property.avg_rating && (
              <p className="text-gray-700 mb-1">
                <span className="font-medium">Average Rating:</span> 
                <span className="text-yellow-500 ml-1">★</span> 
                {Number(property.avg_rating).toFixed(1)}
              </p>
            )}
          </div>

          <div className="mb-6">
            <h2 className="text-lg font-semibold mb-2">Features</h2>
            <div className="grid grid-cols-2 gap-2">
              <p className="text-gray-700">
                <span className="font-medium">Bedrooms:</span> {property.num_bedrooms}
              </p>
              <p className="text-gray-700">
                <span className="font-medium">Bathrooms:</span> {property.num_bathrooms}
              </p>
              <p className="text-gray-700">
                <span className="font-medium">Furnishing:</span> {property.furnish_status}
              </p>
              <p className="text-gray-700">
                <span className="font-medium">Remodel Status:</span> {property.remodel_status}
              </p>
              <p className="text-gray-700">
                <span className="font-medium">Laundry:</span> {property.laundry_location}
              </p>
            </div>
          </div>

          <div className="flex justify-center mt-6">
            <button
              onClick={() => onNavigate('propertyList')}
              className="text-blue-600 hover:underline bg-transparent border-0 cursor-pointer"
            >
              Back to Property List
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PropertyDetails;
